draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // bird
  ctx.fillStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 20, 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 10);
  ctx.lineTo(W/2 - 30, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 10);
  ctx.lineTo(W/2 + 30, H/2 + 30);
  ctx.stroke();

  // nest
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 30 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // twigs
  ctx.beginPath();
  ctx.moveTo(W/2 - 30 - 10 * Math.cos(t), H/2 - 50 - 10 * Math.sin(t));
  ctx.lineTo(W/2 - 40 - 10 * Math.cos(t), H/2 - 60 - 10 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30 + 10 * Math.cos(t), H/2 - 50 - 10 * Math.sin(t));
  ctx.lineTo(W/2 + 40 + 10 * Math.cos(t), H/2 - 60 - 10 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
